#!/bin/bash

# Fetch the initial conditions if they are not present (the DM-only EAGLE
# 25 Mpc low-resolution ICs; gas is generated by SWIFT at start-up).
if [ ! -e EAGLE_L0025N0188_ICs.hdf5 ]
then
    echo "Fetching initial conditions for the KIARA 25Mpc example..."
    ../../EAGLE_ICs/EAGLE_25_low_res/getIC.sh
fi

# Grab the cooling table if it is not present.
# (The chem5 yield tables are in ../chem5.)
if [ ! -e CloudyData_UVB=FG2011_shielded.h5 ]
then
    echo "Fetching the Cloudy cooling table..."
    ../getCloudyTable.sh
fi

# --kiara switches on hydro, self-gravity, cooling, star formation, stars,
# feedback, black holes, FoF (for BH seeding and galaxy properties) and the
# time-step limiter.
../../../swift \
    --cosmology --kiara \
    --threads=16 --pin \
    kiara_25.yml 2>&1 | tee output.log
